'use client'

import { usePathname } from 'next/navigation'
import { useEffect } from 'react'

export function NavigationDirection() {
  const pathname = usePathname()

  useEffect(() => {
    function handleClick(e: MouseEvent) {
      const anchor = (e.target as Element).closest('a')
      if (!anchor) return
      const href = anchor.getAttribute('href')
      if (!href || href.startsWith('#') || href.startsWith('http')) return

      try {
        const targetPath = new URL(href, window.location.origin).pathname
        const currentDepth = pathname.split('/').filter(Boolean).length
        const targetDepth = targetPath.split('/').filter(Boolean).length
        document.documentElement.dataset.navDirection =
          targetDepth > currentDepth ? 'forward' : 'back'
      } catch {
        // ignore invalid URLs
      }
    }

    function handlePopState() {
      document.documentElement.dataset.navDirection = 'back'
    }

    document.addEventListener('click', handleClick, true)
    window.addEventListener('popstate', handlePopState)

    return () => {
      document.removeEventListener('click', handleClick, true)
      window.removeEventListener('popstate', handlePopState)
    }
  }, [pathname])

  return null
}

