    opacity: 0.5;
  }
}

@keyframes slide-out-to-left {
  from {
    transform: translateX(0);
  }
  to {
    transform: translateX(-30%);
  }
}

@keyframes slide-in-from-right {
  from {
    transform: translateX(30%);
  }
  to {
    transform: translateX(0);
  }
}

@keyframes slide-out-to-right {
  from {
    transform: translateX(0);
  }
  to {
    transform: translateX(30%);
  }
}

@keyframes slide-in-from-left {
  from {
    transform: translateX(-30%);
  }
  to {
    transform: translateX(0);
  }
}

@keyframes fade-in {
  from {
    opacity: 0;
    transform: translateY(8px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

html[data-nav-direction="forward"]::view-transition-old(root) {
  animation: slide-out-to-left 300ms ease-out both;
}

html[data-nav-direction="forward"]::view-transition-new(root) {
  animation: slide-in-from-right 300ms ease-out both;
}

html[data-nav-direction="back"]::view-transition-old(root) {
  animation: slide-out-to-right 300ms ease-out both;
}

html[data-nav-direction="back"]::view-transition-new(root) {
  animation: slide-in-from-left 300ms ease-out both;
}

